 struct Frame {Task task;uint32_t source=0,heading=0,savedSource=0,table=0;uint16_t character=0,savedCharacter=0;};
 template<class T>void push(T t,uint32_t source,uint16_t character){if(depth_==frames_.size())throw std::runtime_error("UI semantic depth exceeded");frames_[depth_++].emplace(Frame{Task{t},source,0,0,0,character,0});components_|=1u<<(std::is_same_v<T,Bank>?0:std::is_same_v<T,Program>?1:std::is_same_v<T,Special>?2:std::is_same_v<T,Storage>?3:4);}
 template<class T>void replace(T t){const auto in=*frames_[depth_-1];frames_[depth_-1].reset();--depth_;push(t,in.source,in.character);}
 void pop(){if(!depth_)throw std::runtime_error("Invalid UI semantic completion");frames_[--depth_].reset();if(depth_){frames_[depth_-1]->source=summary_.source;frames_[depth_-1]->character=summary_.character;resumeTop();}}
