 static unsigned byteBus(uint32_t a,int prev){a&=0xffffff;return a<0x400000&&!(prev&1)&&a==(uint32_t(prev)|1u)?0:3;}
 static unsigned bankBus(const Bank&t,int prev){using S=Bank::Stage;switch(t.stage()){case S::WriteRefreshFlag:return byteBus(0x1679c,prev);case S::WriteBankDisplayLatch:return byteBus(0x16792,prev);default:return 3;}}
 static unsigned programBus(const Program&t,int prev){return t.stage()==Program::Stage::WriteProgramLatch?byteBus(0x16792,prev):3;}
